package org.local.donusturucu.qa;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.io.*;import java.util.*;import org.json.*;
public class FileList extends OcrRobustness {
 Activity activity;Object get(String name)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(activity);}void set(String name,Object value)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}void call(String name,Class<?>[]types,Object...args)throws Exception{Method m=activity.getClass().getDeclaredMethod(name,types);m.setAccessible(true);m.invoke(activity,args);}void ui(final Runnable task){runOnMainSync(task);waitForIdleSync();}void require(boolean b)throws Exception{if(!b)throw new IOException("File-list assertion failed");}void invoke(final String name){ui(new Runnable(){public void run(){try{call(name,new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}}});}
 void click(final String field){ui(new Runnable(){public void run(){try{((Button)get(field)).performClick();}catch(Exception e){throw new RuntimeException(e);}}});}
 void load(final File path,int count)throws Exception{ui(new Runnable(){public void run(){try{call("onActivityResult",new Class<?>[]{int.class,int.class,Intent.class},1,Activity.RESULT_OK,new Intent().setData(Uri.fromFile(path)));}catch(Exception e){throw new RuntimeException(e);}}});long until=System.currentTimeMillis()+20000;while(System.currentTimeMillis()<until){Thread.sleep(100);waitForIdleSync();if(!(Boolean)get("busy")&&((List)get("files")).size()==count)return;}throw new IOException("File import timeout");}
 public void onStart(){Bundle result=new Bundle();try{Intent i=new Intent();i.setClassName("org.local.donusturucu","org.local.donusturucu.MainActivity");i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);activity=startActivitySync(i);long until=System.currentTimeMillis()+60000;while(!(Boolean)get("ready")&&System.currentTimeMillis()<until)Thread.sleep(200);require((Boolean)get("ready"));File root=new File(getTargetContext().getExternalFilesDir(null),"file-list-test");root.mkdirs();File text=new File(root,"Belge فارسی.txt"),audio=new File(root,"Ses.wav");FileOutputStream tx=new FileOutputStream(text);tx.write("Merhaba Türkçe Kurmancî فارسی العربية".getBytes("UTF-8"));tx.close();InputStream in=getContext().getAssets().open("short-en.wav");OutputStream out=new FileOutputStream(audio);byte[]buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();out.close();String ht=hash(text),ha=hash(audio);JSONArray rows=new JSONArray();
 for(int repeat=1;repeat<=3;repeat++)for(final boolean ku:new boolean[]{false,true}){JSONObject row=new JSONObject();row.put("repeat",repeat);row.put("language",ku?"ku":"tr");try{invoke("clearFiles");ui(new Runnable(){public void run(){try{set("ku",ku);call("build",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}}});load(text,1);load(audio,2);require(hash((File)get("source")).equals(ha));require(((List)get("actionIds")).contains("transcribe"));ui(new Runnable(){public void run(){try{((Button)((List)get("fileButtons")).get(0)).performClick();}catch(Exception e){throw new RuntimeException(e);}}});require(hash((File)get("source")).equals(ht));require(!((List)get("actionIds")).contains("transcribe"));ui(new Runnable(){public void run(){try{set("busy",true);call("controls",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}}});require(!((Button)get("clearList")).isEnabled()&&!((Button)get("removeFile")).isEnabled());ui(new Runnable(){public void run(){try{set("busy",false);call("controls",new Class<?>[]{});}catch(Exception e){throw new RuntimeException(e);}}});click("removeFile");require(((List)get("files")).size()==1&&hash((File)get("source")).equals(ha));click("clearList");require(((List)get("files")).isEmpty()&&get("source")==null&&!((Button)get("start")).isEnabled());require(hash(text).equals(ht)&&hash(audio).equals(ha));row.put("pass",true);row.put("originals_unchanged",true);}catch(Throwable e){row.put("pass",false);row.put("error",e.toString());}rows.put(row);}
 JSONObject report=new JSONObject();report.put("cases",rows.length());int failures=0;for(int x=0;x<rows.length();x++)if(!rows.getJSONObject(x).getBoolean("pass"))failures++;report.put("failures",failures);report.put("rows",rows);report.put("scope","Actual Activity import callback with local file URIs and Button.performClick; not external SAF picker touch automation");Writer w=new OutputStreamWriter(new FileOutputStream(new File(root,"report.json")),"UTF-8");w.write(report.toString(2));w.close();result.putString("report",report.toString());finish(failures==0?0:1,result);
 }catch(Throwable e){result.putString("error",e.toString());finish(1,result);}}
}
